#!/usr/bin/env python3
"""Generate/check the deterministic compatibility identity, excluding generated files."""
from pathlib import Path
import hashlib,json,re,sys
root=Path(__file__).resolve().parents[1]
paths=['src/system/recf_control_core.c','src/system/recf_control_state.c','src/system/system_daemon.c',
       'src/system/dev/ser_daemon.c','src/devices/controller.c','src/devices/vdml_motors.c',
       'src/devices/vdml_ext_adi.c','include/pros/recf_control_state.h',
       'include/system/recf_control_core.h','include/system/recf_control_state.h']
sources={p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in paths}
fingerprint=hashlib.sha256(json.dumps(sources,sort_keys=True,separators=(',',':')).encode()).hexdigest()[:16]
descriptor=f'RECF_CONTROL_STATE 4.2.2 1.4.0 {fingerprint} 0000000f'
identity={'family':'RECF_CONTROL_STATE','pros':'4.2.2','recf':'1.4.0','fingerprint':fingerprint,
          'capabilities':{'native_practice':1,'heartbeat_watchdog':2,'adi_guard':4,'identity':8},
          'capability_mask':'0000000f','descriptor':descriptor,'sources':sources,
          'cryptographic_authenticity':False}
header='/* Generated by tools/kernel_identity.py. Compatibility identity only. */\n#pragma once\n#define RECF_KERNEL_DESCRIPTOR '+json.dumps(descriptor)+'\n'
app=root/'tools/python-practice-watchdog/controller_serial_test.py'
if '--check' in sys.argv:
    assert json.loads((root/'kernel-identity.json').read_text())==identity,'Identity source hashes are stale'
    assert (root/'include/system/recf_kernel_identity.h').read_text()==header,'Kernel header identity mismatch'
    assert 'EXPECTED_KERNEL = '+repr(descriptor) in app.read_text(),'Desktop expected identity mismatch'
    print('Kernel and desktop identity source hashes verified:',fingerprint)
else:
    (root/'kernel-identity.json').write_text(json.dumps(identity,indent=2)+'\n')
    (root/'include/system/recf_kernel_identity.h').write_text(header)
    app.write_text(re.sub(r'^EXPECTED_KERNEL = .*$', 'EXPECTED_KERNEL = '+repr(descriptor), app.read_text(),flags=re.M))
    print('Generated:',descriptor)
